describe("Cart — pricing pipeline", () => {
  it("applies discount → tax on discounted subtotal → shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(475),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("a", 5000), 1);
    const totals = cart.totals();

    expect(totals.subtotalCents).toBe(5000);
    expect(totals.discountCents).toBe(500);
    // tax is called with discounted subtotal (5000-500=4500) and region
    expect(tax.computeTaxCents).toHaveBeenCalledWith(4500, "US-CA");
    expect(totals.taxCents).toBe(475);
    // shipping is called with lines and discounted subtotal
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      4500,
    );
    expect(totals.shippingCents).toBe(300);
    // total = discountedSubtotal + tax + shipping = 4500 + 475 + 300
    expect(totals.totalCents).toBe(5275);
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount exceeding subtotal to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 9999,
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to NoDiscount, NoTax, FreeShipping, US region", () => {
    const cart = new Cart();
    cart.add(product("a", 1500), 3);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4500);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(4500);
  });

  it("computes subtotal across multiple lines", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    cart.add(product("b", 500), 3);
    // 2000 + 1500 = 3500
    expect(cart.totals().subtotalCents).toBe(3500);
  });
});

describe("Cart.checkout()", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart({ region: "US" });
    cart.add(product("p1", 1000), 2);
    cart.add(product("p2", 2000, { weightGrams: 300 }), 1);
  });

  it("returns totals and lines without collaborators", async () => {
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(4000);
    expect(result.lines).toHaveLength(2);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockResolvedValueOnce(1100) // p1 updated
        .mockResolvedValueOnce(2200), // p2 updated
    };
    const result = await cart.checkout({ priceFetcher });
    // 1100*2 + 2200*1 = 4400
    expect(result.totals.subtotalCents).toBe(4400);
  });

  it("propagates priceFetcher errors", async () => {
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price error",
    );
  });

  it("throws InventoryError when item is unavailable", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("p1");
      expect(invErr.requested).toBe(2);
      expect(invErr.message).toBe("sold out");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 1,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.requested).toBe(2);
      expect(invErr.available).toBe(1);
    }
  });

  it("passes checkout when inventory is sufficient", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(4000);
    expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
  });

  it("passes checkout when availableQuantity equals requested", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true, availableQuantity: 2 })
        .mockResolvedValueOnce({ available: true, availableQuantity: 1 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(4000);
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal = 4000, no discount, tax = floor(4000 * 0.1) = 400
    expect(result.totals.taxCents).toBe(400);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("propagates asyncTaxProvider failure", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("composes price refresh + discount + async tax + shipping", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: (sub: number) => Math.floor(sub * 0.1),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cartWithSeams = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cartWithSeams.add(product("p1", 1000), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };

    const result = await cartWithSeams.checkout({
      priceFetcher,
      asyncTaxProvider,
    });

    // refreshed subtotal: 1200*2 = 2400
    expect(result.totals.subtotalCents).toBe(2400);
    // discount: 10% of 2400 = 240
    expect(result.totals.discountCents).toBe(240);
    // discountedSubtotal = 2400 - 240 = 2160
    // tax: floor(2160 * 0.0875) = floor(189) = 189
    expect(result.totals.taxCents).toBe(189);
    expect(result.totals.shippingCents).toBe(500);
    // total = 2160 + 189 + 500 = 2849
    expect(result.totals.totalCents).toBe(2849);
  });

  it("generates default InventoryError message when no reason given", async () => {
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.message).toContain("insufficient stock");
      expect(invErr.message).toContain("p1");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 999_99, -50])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 = 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("floors fractional cents (10% of 999 = 99)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(999)).toBe(99);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(25);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("100% returns the full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("floors correctly for 33% of 100", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 100 * 33 / 100 = 33
      expect(policy.computeDiscountCents(100)).toBe(33);
    });

    it("floors correctly for 33% of 101", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 101 * 33 / 100 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(5000);
      expect(policy.computeDiscountCents(2000)).toBe(2000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amount equals subtotal", () => {
