toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [10000, "US"],
    [500, "FR"],
  ])("returns 0 for taxable %i in region %s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative default rate", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects default rate above 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects Infinity default rate", () => {
      expect(() => new RegionalTaxCalculator({}, Infinity)).toThrow(RangeError);
    });

    it("rejects invalid rate for a region", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("rejects negative rate for a region", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": -0.1 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(
        () => new RegionalTaxCalculator({ "US": 0, "FR": 1 }, 0.5),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, "FR": 0.2 },
      0.05,
    );

    it("looks up rate for known region", () => {
      // 10000 * 0.0875 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("uses default rate for unknown region", () => {
      // 10000 * 0.05 = 500
      expect(calc.computeTaxCents(10000, "DE")).toBe(500);
    });

    it("floors fractional cents", () => {
      // 999 * 0.0875 = 87.4125 → 87
      expect(calc.computeTaxCents(999, "US-CA")).toBe(87);
    });

    it("returns 0 for zero taxable amount", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable amount", () => {
      expect(calc.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("defaults to 0 rate when no default specified", () => {
      const calc2 = new RegionalTaxCalculator({ "US": 0.1 });
      expect(calc2.computeTaxCents(10000, "UNKNOWN")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for non-positive taxable amount without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("should not be called");
      },
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("computes tax using the async rate and floors the result", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.0875,
    };
    const calc = new AsyncTaxCalculator(provider);
    // 999 * 0.0875 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US-CA")).toBe(87);
  });

  it("computes exact tax with no rounding needed", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(10000, "US")).toBe(1000);
  });

  it("throws RangeError when provider returns rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 1.5,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => -0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => NaN,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("network failure");
      },
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "network failure",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight × quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 3 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
    ];
    // 200*3 + 500*2 = 600 + 1000 = 1600
    expect(totalLineWeightGrams(lines)).toBe(1600);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

