toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

const makeUnweightedLine = (id: string, quantity: number): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000 },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts zero freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2000)).toBe(
        599,
      );
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(
        599,
      );
    });

    it("charges flat fee without freeOver configured", () => {
      const calc = new FlatShippingCalculator(1000);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 100_000),
      ).toBe(1000);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 5.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 5000, costCents: 1200 },
      ],
      2000,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for items with no weight", () => {
      expect(
        calc.computeShippingCents([makeUnweightedLine("a", 2)], 1000),
      ).toBe(0);
    });

    it("selects the first bracket when weight falls within it", () => {
      // 500g total → first bracket (≤500g → 300)
      expect(
        calc.computeShippingCents([makeLine("a", 250, 2)], 1000),
      ).toBe(300);
    });

    it("selects middle bracket at exact boundary", () => {
      // 500g exactly → first bracket (≤500 → 300)
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 1000),
      ).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary by 1g", () => {
      // 501g → second bracket (≤2000 → 700)
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 1000),
      ).toBe(700);
    });

    it("selects the last bracket at its upper boundary", () => {
      // 5000g → third bracket (≤5000 → 1200)
      expect(
        calc.computeShippingCents([makeLine("a", 2500, 2)], 1000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 5001g → overflow → 2000
      expect(
        calc.computeShippingCents([makeLine("a", 5001, 1)], 1000),
      ).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calcNoOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 400 },
        { upToGrams: 3000, costCents: 900 },
      ]);
      // 5000g → last bracket cost 900
      expect(
        calcNoOverflow.computeShippingCents([makeLine("a", 5000, 1)], 1000),
      ).toBe(900);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ]);
      // 300g → first bracket after sort (≤500 → 300)
      expect(
        unordered.computeShippingCents([makeLine("a", 300, 1)], 1000),
      ).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 200*2 + 300*1 = 700 → second bracket (≤2000 → 700)
      const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });
  });
});

